static void ঘটনা(int মালিক_বস্তু,int মান){if(항목수[মালিক_বস্তু]<16){ঘটনা_তালিকা[মালিক_বস্তু][(첫항목[মালিক_বস্তু]+항목수[মালিক_বস্তু])%16]=মান;항목수[মালিক_বস্তু]++;}}
